#include <array>
#include <cstddef>

struct MarketSnapshot {
    std::array<std::byte, 64> bytes;
};

void closure_sizes() {
    int quantity = 10;
    int price = 101;
    MarketSnapshot snapshot{};

    auto empty = [] {};
    auto one_int = [quantity] { return quantity; };
    auto two_refs = [&quantity, &price] { return quantity * price; };
    auto full_snapshot = [snapshot] { return snapshot.bytes[0]; };

    static_assert(sizeof(empty) == 1);
    static_assert(sizeof(one_int) >= sizeof(int));
    static_assert(sizeof(two_refs) <= 2 * sizeof(void*));

    // A by-value capture is a data member: the snapshot's 64 bytes travel in
    // every copy of the closure. A reference capture stays pointer-sized no
    // matter how large the referent is - and dangles just as easily.
    static_assert(sizeof(full_snapshot) >= sizeof(MarketSnapshot));
}

#include <iostream>

struct Tick {
    int price;
};

using TickCallback = void (*)(const Tick&);

void register_tick_callback(TickCallback callback) {
    callback(Tick{101});
}

namespace {
constexpr int fee = 2;
}

void install_callback() {
    auto handler = [](const Tick& tick) {
        std::cout << tick.price - fee << '\n';
    };

    static_assert(sizeof(handler) == 1);

    // Unary + has no overload for a closure type, so the compiler applies the
    // implicit function-pointer conversion. Without it, a function template on
    // the other side could deduce the unique closure type instead.
    register_tick_callback(+handler);
}

