#include <functional>
#include <utility>
#include <vector>

struct Order {
    int id;
};

void post(std::function<void()> callback);
void send(const std::vector<Order>& orders);

void queue_orders_badly() {
    std::vector<Order> buffer{{1}, {2}};

    post([&buffer] {
        send(buffer);   // UB when invoked later: buffer is already dead
    });
}

void queue_orders() {
    std::vector<Order> buffer{{1}, {2}};

    // Init-capture (C++14): a new closure member initialised by moving, so the
    // vector's allocation transfers into the closure and the closure owns it.
    post([orders = std::move(buffer)] {
        send(orders);
    });

    // buffer is valid but moved-from here: it may be queried, assigned to, or
    // destroyed, and nothing else.

    // Note: owning the buffer fixes the *source's* lifetime, not copy cost.
    // Passing this closure by value would duplicate the whole vector.
}

#include <functional>
#include <memory>

class EventLoop {
public:
    void post(std::function<void()> callback);
};

class ExchangeSession : public std::enable_shared_from_this<ExchangeSession> {
public:
    explicit ExchangeSession(int venue) : venue_(venue) {}

    // Precondition: this session outlives every invocation the loop will make.
    // Choose when the callback is synchronous or the ownership is obvious.
    void register_borrowed(EventLoop& loop) {
        loop.post([this] { on_fill(42); });
    }

    // Copies the whole session at capture time. Independent of the original's
    // lifetime, and deliberately blind to later changes. Choose for an
    // immutable delayed snapshot of a small object.
    void register_snapshot(EventLoop& loop) {
        loop.post([*this] { on_fill(42); });
    }

    // Observes without owning; the work is skipped if the session is gone.
    // Choose when lifetime is dynamic and cancellation is acceptable.
    void register_guarded(EventLoop& loop) {
        loop.post([weak = weak_from_this()] {
            if (auto owner = weak.lock()) {
                owner->on_fill(42);
            }
        });
    }

private:
    void on_fill(int order_id) const;
    int venue_;
};

#include <iostream>

void generators() {
    auto generator = [sequence = 0]() mutable {
        return ++sequence;
    };

    auto first = generator;
    auto second = generator;

    // Each copy carries its own `sequence` member, so both print 1: standard
    // algorithms are permitted to copy their callable, and the accumulated
    // state can end up in a copy you never see.
    std::cout << first() << ' ' << second() << '\n';

    // Shared state lives outside the closure. The closure borrows it, so
    // `shared` must outlive every invocation - here, the rest of this scope.
    int shared = 0;
    auto counted = [&shared] {
        return ++shared;
    };

    counted();
    auto counted_copy = counted;
    counted_copy();

    std::cout << shared << '\n';   // 2: both closures updated the same object
}

#include <iostream>

class FunctionRef {
public:
    template<class F>
    FunctionRef(F& function) noexcept
        : object_(&function),
          invoke_([](void* object, int value) {
              return (*static_cast<F*>(object))(value);
          }) {}

    int operator()(int value) const {
        return invoke_(object_, value);
    }

private:
    void* object_;
    int (*invoke_)(void*, int);
};

// Concrete closure type preserved: the call usually inlines and constants
// propagate. Cost: one instantiation per callable type, definition in header.
template<class Handler>
int apply_template(int value, Handler handler) {
    return handler(value);
}

// Erased: one non-template implementation, but the call goes through an
// opaque invoker the optimizer normally cannot see past. Owns nothing and
// allocates nothing - the referenced callable must outlive every call.
int apply_ref(int value, FunctionRef handler) {
    return handler(value);
}

int main() {
    int bias = 1;
    auto add_bias = [bias](int value) { return value + bias; };

    std::cout << apply_template(41, add_bias) << ' '
              << apply_ref(41, add_bias) << '\n';
}
